export const KOTOBA_BY_BOOK: Record<BookId, KotobaChapter[]> = {
  n5: N5_KOTOBA_CHAPTERS,
  n4: N4_KOTOBA_CHAPTERS,
};

export const N5_KOTOBA_WORDS: KotobaWord[] = N5_KOTOBA_CHAPTERS.flatMap(ch => ch.words);
export const N4_KOTOBA_WORDS: KotobaWord[] = N4_KOTOBA_CHAPTERS.flatMap(ch => ch.words);
export const ALL_KOTOBA_WORDS: KotobaWord[] = [...N5_KOTOBA_WORDS, ...N4_KOTOBA_WORDS];

export function getKotobaChapters(bookId: BookId): KotobaChapter[] {
  return KOTOBA_BY_BOOK[bookId];
}

export function getKotobaWords(bookId: BookId): KotobaWord[] {
  return bookId === "n5" ? N5_KOTOBA_WORDS : N4_KOTOBA_WORDS;
}
